\draw[->,black] (0,-0.85)--(0,2.55) node[above] {$y$};
\draw[thick,curveblue,domain=-0.5235987756:0.5235987756,samples=81,variable=\t] plot ({sin(deg(\t))},{\t});
\draw[thick,curvered,dashed,domain=1.0471975512:2.0943951024,samples=81,variable=\t] plot ({cos(deg(\t))},{\t});
\fill[curveblue] (-0.5,-0.5235987756) circle (1.5pt);
\fill[curveblue] (0.5,0.5235987756) circle (1.5pt);
